import 'dart:convert';
import 'dart:io';

import 'package:crypto/crypto.dart';

const _owner = 'im_l10n_catalog';
const _markerName = '.im_l10n_catalog_generated';
const _yamlHeader = '# Generated by im_l10n_catalog. Do not edit.\n';

final class CatalogException implements Exception {
  const CatalogException(this.message);
  final String message;
  @override
  String toString() => message;
}

/// Selects ARBs before compilation. All validation precedes output mutation.
///
/// [outputDir] in the consumer config must be below `lib/`, and is wholly
/// generated. Keep hand-written overrides outside that directory.
Map<String, Object?> generateBundle({
  required Directory packageRoot,
  required Directory consumerRoot,
  String configPath = 'l10n.bundle.json',
  bool checkOnly = false,
}) {
  final root = Directory(consumerRoot.resolveSymbolicLinksSync());
  final configFile = _safeFile(root, configPath, 'configPath');
  final config = _readObject(configFile);
  _requireSchema(config, configFile.path);
  final index = _readObject(File('${packageRoot.path}/catalog/index.json'));
  _requireSchema(index, 'catalog/index.json');
  final version = _string(index, 'packageVersion');
  final pubspec = File('${packageRoot.path}/pubspec.yaml').readAsStringSync();
  final pubspecVersion = RegExp(
    r'^version:\s*([^\s#]+)',
    multiLine: true,
  ).firstMatch(pubspec)?.group(1);
  if (version != pubspecVersion || config['catalogVersion'] != version) {
    throw CatalogException(
      'Version mismatch: config=${config['catalogVersion']}, '
      'catalog=$version, package=$pubspecVersion. Pin the same version.',
    );
  }
  Map<String, dynamic>? profile;
  final profileName = config['profile'];
  if (profileName != null) {
    if (profileName is! String ||
        !RegExp(r'^[a-z][a-z0-9_]*$').hasMatch(profileName)) {
      throw const CatalogException('Invalid consumer profile.');
    }
    profile = _readObject(
        File('${packageRoot.path}/catalog/profiles/$profileName.json'));
    _requireSchema(profile, 'consumer profile');
  }
  final locales = _strings(config, 'locales');
  final availableLocales = _strings(index, 'locales');
  _assertSubset(locales, availableLocales.toSet(), 'locale');
  if (profile != null) {
    _assertSubset(
        locales, _strings(profile, 'locales').toSet(), 'profile locale');
  }
  for (final locale in availableLocales) {
    if (!RegExp(r'^[a-z]{2,3}(?:_[A-Za-z0-9]+)*$').hasMatch(locale)) {
      throw CatalogException('Invalid catalog locale: $locale.');
    }
  }
  final defaultLocale = _string(index, 'defaultLocale');
  _assertSubset([defaultLocale], availableLocales.toSet(), 'default locale');
  final templateLocale = _string(config, 'templateLocale');
  _assertSubset([templateLocale], locales.toSet(), 'template locale');
  final moduleIndex = _object(index['modules'], 'catalog modules');
  final allKeys = <String>{};
  final keysByModule = <String, List<String>>{};
  for (final entry in moduleIndex.entries) {
    if (!RegExp(r'^[a-z][a-z0-9_]*$').hasMatch(entry.key)) {
      throw CatalogException('Invalid module name: ${entry.key}.');
    }
    final keys = _stringList(entry.value, 'module ${entry.key}');
    for (final key in keys) {
      if (!RegExp(r'^[a-z][A-Za-z0-9]*$').hasMatch(key)) {
        throw CatalogException('Invalid ARB key: $key.');
      }
      if (!allKeys.add(key)) {
        throw CatalogException('Duplicate catalog key across modules: $key.');
      }
    }
    keysByModule[entry.key] = keys;
  }
  final modules = _strings(config, 'modules');
  _assertSubset(modules, moduleIndex.keys.toSet(), 'module');
  final moduleKeys = modules.expand((m) => keysByModule[m]!).toSet();
  if (profile != null) {
    final profileKeys = _strings(profile, 'keys');
    _assertSubset(profileKeys, allKeys, 'profile key');
    moduleKeys.retainAll(profileKeys);
  }
  final includeKeys = config.containsKey('includeKeys')
      ? _strings(config, 'includeKeys')
      : moduleKeys.toList();
  _assertSubset(includeKeys, moduleKeys, 'included key in selected modules');
  final excludeKeys = config.containsKey('excludeKeys')
      ? _strings(config, 'excludeKeys', allowEmpty: true)
      : <String>[];
  _assertSubset(excludeKeys, moduleKeys, 'excluded key in selected modules');
  final keys = includeKeys.toSet().difference(excludeKeys.toSet()).toList()
    ..sort();
  if (profile != null) {
    final order = _strings(profile, 'keys');
    keys.sort((a, b) => order.indexOf(a).compareTo(order.indexOf(b)));
  }
  if (keys.isEmpty) {
    throw const CatalogException('Selection contains no translation keys.');
  }
  final selectedKeys = keys.toSet();
  final outputPath = _string(config, 'outputDir');
  if (!outputPath.startsWith('lib/')) {
    throw const CatalogException(
      'outputDir must be below lib/, for example lib/l10n.',
    );
  }
  final output = _safeDirectory(root, outputPath, 'outputDir');
  final flat = config['layout'] == 'flat';
  if (config['layout'] != null &&
      config['layout'] != 'flat' &&
      config['layout'] != 'nested') {
    throw const CatalogException('layout must be flat or nested.');
  }
  final outputClass = _string(config, 'outputClass');
  if (!RegExp(r'^[A-Z][A-Za-z0-9]*$').hasMatch(outputClass)) {
    throw const CatalogException('outputClass must be a Dart class name.');
  }
  final overrides = config['overridesDir'] == null
      ? null
      : _safeDirectory(root, _string(config, 'overridesDir'), 'overridesDir');
  if (overrides != null && _overlaps(overrides.path, output.path)) {
    throw const CatalogException('overridesDir must be outside outputDir.');
  }
  if (_overlaps(packageRoot.absolute.path, output.path)) {
    throw const CatalogException(
      'outputDir must not overlap the catalog package.',
    );
  }

  // Read the catalog's default language to retain the authoritative parameter
  // metadata, even when that language is excluded from the consumer bundle.
  final source = <String, Map<String, Map<String, dynamic>>>{};
  for (final module in modules) {
    source[module] = {};
    for (final locale in {...locales, defaultLocale}) {
      final file = File('${packageRoot.path}/catalog/$module/app_$locale.arb');
      final arb = _readObject(file);
      if (arb['@@locale'] != locale) {
        throw CatalogException('Locale marker mismatch in ${file.path}.');
      }
      source[module]![locale] = arb;
    }
  }
  final metadata = <String, Map<String, dynamic>>{};
  final expectedParameters = <String, Set<String>>{};
  for (final module in modules) {
    final defaults = source[module]![defaultLocale]!;
    for (final key in keysByModule[module]!.where(selectedKeys.contains)) {
      final defaultOverrides =
          profile?['overrides']?[defaultLocale] as Map<String, dynamic>?;
      final value = _translation(
          {...defaults, ...?defaultOverrides}, key, '$module/$defaultLocale');
      final parameters = _parameters(value);
      final sourceMeta =
          profile?['metadata']?[defaultLocale]?["@$key"] ?? defaults['@$key'];
      final meta = sourceMeta == null
          ? <String, dynamic>{}
          : _object(sourceMeta, '@$key');
      _validateMetadata(key, meta, parameters, '$module/$defaultLocale');
      metadata[key] = meta;
      expectedParameters[key] = parameters;
    }
  }
  final outputArbs = <String, Map<String, dynamic>>{};
  final overriddenKeys = <String, List<String>>{};
  for (final locale in locales) {
    final arb = <String, dynamic>{'@@locale': locale};
    for (final module in modules) {
      final translations = source[module]![locale]!;
      for (final key in keysByModule[module]!.where(selectedKeys.contains)) {
        final profileOverrides =
            profile?['overrides']?[locale] as Map<String, dynamic>?;
        final text = _translation(
            {...translations, ...?profileOverrides}, key, '$module/$locale');
        if (profile == null)
          _assertParameters(key, text, expectedParameters[key]!, locale);
        if (profile == null && translations['@$key'] != null) {
          final localizedMeta = _object(translations['@$key'], '@$key');
          _validateMetadata(
            key,
            localizedMeta,
            expectedParameters[key]!,
            locale,
          );
          if (!_sameMap(_types(localizedMeta), _types(metadata[key]!))) {
            throw CatalogException(
              'Placeholder type mismatch for $key in $locale.',
            );
          }
        }
        arb[key] = text;
        if (profile == null) {
          if (metadata[key]!.isNotEmpty) arb['@$key'] = metadata[key];
        } else {
          final sourceMetadata = profile['metadata'] == null
              ? translations['@$key']
              : profile['metadata'][locale]?["@$key"];
          if (sourceMetadata != null) arb['@$key'] = sourceMetadata;
        }
      }
    }
    overriddenKeys[locale] = [];
    if (overrides != null) {
      final file = File('${overrides.path}/$locale.json');
      if (file.existsSync()) {
        final replacements = _readObject(file);
        for (final entry in replacements.entries) {
          if (!selectedKeys.contains(entry.key)) {
            throw CatalogException(
              'Override ${entry.key} in $locale is unknown or excluded.',
            );
          }
          if (entry.value is! String ||
              (entry.value as String).trim().isEmpty) {
            throw CatalogException(
              'Override ${entry.key} in $locale must be nonempty text.',
            );
          }
          _assertParameters(
            entry.key,
            entry.value as String,
            expectedParameters[entry.key]!,
            'override/$locale',
          );
          arb[entry.key] = entry.value;
          overriddenKeys[locale]!.add(entry.key);
        }
        overriddenKeys[locale]!.sort();
      }
    }
    // A canonical order keeps generated diffs and hashes deterministic.
    outputArbs[locale] = {
      '@@locale': locale,
      for (final key in keys) ...{
        key: arb[key],
        if (arb.containsKey('@$key')) '@$key': arb['@$key'],
      },
    };
  }

  final receiptFile = File('${root.path}/l10n.bundle.lock.json');
  final yamlFile = File('${root.path}/l10n.yaml');
  _checkOwnedOutput(output, flat: flat);
  if (yamlFile.existsSync() &&
      !yamlFile.readAsStringSync().startsWith(_yamlHeader)) {
    throw const CatalogException(
      'Existing l10n.yaml is not generated by this tool.',
    );
  }
  if (receiptFile.existsSync() &&
      _readObject(receiptFile)['generatedBy'] != _owner) {
    throw const CatalogException(
      'Existing bundle lock is not generated by this tool.',
    );
  }
  for (final file in [yamlFile, receiptFile]) {
    _rejectSymlinks(root, file.path);
  }
  final receipt = <String, Object?>{
    'generatedBy': _owner,
    'schemaVersion': 1,
    'catalogPackage': _owner,
    'catalogVersion': version,
    'locales': locales,
    'templateLocale': templateLocale,
    'modules': modules,
    'keys': keys,
    'excludeKeys': excludeKeys,
    if (config.containsKey('includeKeys')) 'includeKeys': includeKeys,
    'overrides': overriddenKeys,
    'outputDir': outputPath,
    'outputClass': outputClass,
    if (profileName != null) 'profile': profileName,
    if (flat) 'layout': 'flat',
    'bundleSha256':
        sha256.convert(utf8.encode(jsonEncode(outputArbs))).toString(),
  };

  final arbRelative = flat ? outputPath : '$outputPath/arb';
  final generatedRelative = flat ? outputPath : '$outputPath/generated';
  final yaml = '''${_yamlHeader}arb-dir: $arbRelative
template-arb-file: app_$templateLocale.arb
output-dir: $generatedRelative
output-localization-file: app_localizations.dart
output-class: $outputClass
nullable-getter: false
preferred-supported-locales: [${locales.join(', ')}]
''';
  if (checkOnly) {
    for (final entry in outputArbs.entries) {
      final file = File('${root.path}/$arbRelative/app_${entry.key}.arb');
      if (!file.existsSync() || !_sameJson(_readObject(file), entry.value)) {
        throw CatalogException(
            'Generated ARB is stale: ${file.path}. Run sync_l10n.');
      }
    }
    final localeFiles = Directory('${root.path}/$arbRelative')
        .listSync()
        .whereType<File>()
        .where((file) => RegExp(r'^app_[A-Za-z0-9_]+\.arb$')
            .hasMatch(file.uri.pathSegments.last));
    if (localeFiles.length != locales.length ||
        !yamlFile.existsSync() ||
        yamlFile.readAsStringSync() != yaml ||
        !receiptFile.existsSync() ||
        !_sameJson(_readObject(receiptFile), receipt)) {
      throw const CatalogException(
          'Generated translation configuration or receipt is stale.');
    }
    return receipt;
  }
  // No mutations occur above this point. Delete only a validated, marked tree.
  if (output.existsSync()) output.deleteSync(recursive: true);
  final arbOutput = Directory('${root.path}/$arbRelative')
    ..createSync(recursive: true);
  File('${output.path}/$_markerName').writeAsStringSync('$_owner\n');
  for (final entry in outputArbs.entries) {
    _writeJson(File('${arbOutput.path}/app_${entry.key}.arb'), entry.value);
  }
  yamlFile.writeAsStringSync(yaml);
  _writeJson(receiptFile, receipt);
  return receipt;
}

bool _sameJson(Object? a, Object? b) {
  if (a is Map && b is Map)
    return a.length == b.length &&
        a.keys.every((key) => b.containsKey(key) && _sameJson(a[key], b[key]));
  if (a is List && b is List)
    return a.length == b.length &&
        List.generate(a.length, (i) => i).every((i) => _sameJson(a[i], b[i]));
  return a == b;
}

void _checkOwnedOutput(Directory directory, {bool flat = false}) {
  if (!directory.existsSync()) return;
  final entries = directory.listSync(followLinks: false);
  if (entries.isEmpty) return;
  final marker = File('${directory.path}/$_markerName');
  if (!marker.existsSync() || marker.readAsStringSync() != '$_owner\n') {
    throw const CatalogException(
      'Output directory is not owned by this generator.',
    );
  }
  for (final entry in directory.listSync(recursive: true, followLinks: false)) {
    if (entry is Link) {
      throw const CatalogException('Symlink found inside generated output.');
    }
    final relative = entry.path.substring(directory.path.length + 1);
    final allowed = flat
        ? entry is File &&
            (relative == _markerName ||
                RegExp(r'^app_[A-Za-z0-9_]+\.arb$').hasMatch(relative) ||
                RegExp(r'^app_localizations(?:_[A-Za-z0-9_]+)?\.dart$')
                    .hasMatch(relative))
        : entry is Directory
            ? relative == 'arb' || relative == 'generated'
            : relative == _markerName ||
                RegExp(r'^arb/app_[a-zA-Z0-9_]+\.arb$').hasMatch(relative) ||
                RegExp(
                  r'^generated/app_localizations(?:_[a-zA-Z0-9_]+)?\.dart$',
                ).hasMatch(relative);
    if (!allowed) {
      throw CatalogException('Unowned file in generated output: $relative.');
    }
  }
}

bool _overlaps(String a, String b) =>
    a == b || a.startsWith('$b/') || b.startsWith('$a/');

File _safeFile(Directory root, String path, String label) {
  _validateRelativePath(path, label);
  final result = File('${root.path}/$path');
  _rejectSymlinks(root, result.path);
  return result;
}

Directory _safeDirectory(Directory root, String path, String label) {
  _validateRelativePath(path, label);
  final result = Directory('${root.path}/$path');
  _rejectSymlinks(root, result.path);
  return result;
}

void _validateRelativePath(String path, String label) {
  if (path.isEmpty ||
      path.startsWith('/') ||
      path.contains('\\') ||
      path
          .split('/')
          .any((part) => part.isEmpty || part == '.' || part == '..') ||
      !RegExp(r'^[A-Za-z0-9_./-]+$').hasMatch(path)) {
    throw CatalogException(
      '$label must be a safe relative path without traversal.',
    );
  }
}

void _rejectSymlinks(Directory root, String path) {
  var current = root.path;
  final relative = path.substring(root.path.length + 1);
  for (final part in relative.split('/')) {
    current = '$current/$part';
    if (FileSystemEntity.typeSync(current, followLinks: false) ==
        FileSystemEntityType.link) {
      throw CatalogException('Symlink paths are not supported: $current.');
    }
  }
}

Map<String, dynamic> _readObject(File file) {
  if (!file.existsSync()) throw CatalogException('Missing file: ${file.path}.');
  try {
    return _object(jsonDecode(file.readAsStringSync()), file.path);
  } on FormatException catch (error) {
    throw CatalogException('Invalid JSON in ${file.path}: ${error.message}.');
  }
}

Map<String, dynamic> _object(Object? value, String label) {
  if (value is! Map<String, dynamic>) {
    throw CatalogException('$label must be a JSON object.');
  }
  return value;
}

void _requireSchema(Map<String, dynamic> value, String label) {
  if (value['schemaVersion'] != 1) {
    throw CatalogException('Unsupported schemaVersion in $label.');
  }
}

String _string(Map<String, dynamic> object, String key) {
  final value = object[key];
  if (value is! String || value.isEmpty) {
    throw CatalogException('$key must be a nonempty string.');
  }
  return value;
}

List<String> _strings(
  Map<String, dynamic> object,
  String key, {
  bool allowEmpty = false,
}) =>
    _stringList(object[key], key, allowEmpty: allowEmpty);

List<String> _stringList(
  Object? value,
  String label, {
  bool allowEmpty = false,
}) {
  if (value is! List ||
      value.any((entry) => entry is! String || entry.isEmpty)) {
    throw CatalogException('$label must be a string list.');
  }
  final list = value.cast<String>();
  if ((!allowEmpty && list.isEmpty) || list.toSet().length != list.length) {
    throw CatalogException(
      '$label must be nonempty and contain no duplicates.',
    );
  }
  return list;
}

void _assertSubset(Iterable<String> values, Set<String> allowed, String label) {
  for (final value in values) {
    if (!allowed.contains(value))
      throw CatalogException('Unknown $label: $value.');
  }
}

String _translation(Map<String, dynamic> arb, String key, String label) {
  final value = arb[key];
  if (value is! String || value.trim().isEmpty) {
    throw CatalogException('Missing translation $key in $label.');
  }
  return value;
}

Map<String, String> _types(Map<String, dynamic> meta) {
  final placeholders = meta['placeholders'] == null
      ? <String, dynamic>{}
      : _object(meta['placeholders'], 'placeholders');
  return placeholders.map((key, value) {
    final type = _object(value, 'placeholder $key')['type'] ?? 'Object';
    if (type is! String)
      throw CatalogException('Invalid parameter type for $key.');
    return MapEntry(key, type);
  });
}

bool _sameMap(Map<String, String> a, Map<String, String> b) =>
    a.length == b.length &&
    a.entries.every((entry) => b[entry.key] == entry.value);

void _validateMetadata(
  String key,
  Map<String, dynamic> meta,
  Set<String> parameters,
  String label,
) {
  if (!_sameSet(_types(meta).keys.toSet(), parameters)) {
    throw CatalogException('Placeholder metadata mismatch for $key in $label.');
  }
}

void _assertParameters(
  String key,
  String message,
  Set<String> expected,
  String label,
) {
  if (!_sameSet(_parameters(message), expected)) {
    throw CatalogException('Placeholder names mismatch for $key in $label.');
  }
}

bool _sameSet(Set<String> a, Set<String> b) =>
    a.length == b.length && a.containsAll(b);

// Inspect ICU variable structure without interpreting or rendering messages.
// Branch wrapper text is not mistaken for a parameter (e.g. other {Ready}).
// Flutter gen-l10n remains responsible for the complete ICU grammar.
Set<String> _parameters(String message) {
  final names = <String>{};
  void scan(String text) {
    for (var i = 0; i < text.length; i++) {
      if (text[i] == '}') {
        throw const CatalogException('Unmatched closing brace in translation.');
      }
      if (text[i] != '{') continue;
      final close = _closingBrace(text, i);
      final body = text.substring(i + 1, close).trim();
      final match = RegExp(
        r'^([A-Za-z_][A-Za-z0-9_]*)\s*([,]?)',
      ).firstMatch(body);
      if (match == null ||
          (match.group(2)!.isEmpty && match.end != body.length)) {
        throw const CatalogException('Malformed placeholder in translation.');
      }
      names.add(match.group(1)!);
      if (match.group(2) == ',') {
        final rest = body.substring(match.end).trimLeft();
        final comma = rest.indexOf(',');
        if (comma >= 0 &&
            {
              'plural',
              'select',
              'selectordinal',
            }.contains(rest.substring(0, comma).trim())) {
          var branches = rest.substring(comma + 1).trimLeft();
          branches = branches.replaceFirst(RegExp(r'^offset:\s*\d+\s*'), '');
          while (branches.isNotEmpty) {
            final branch = RegExp(
              r'^(?:=\d+(?:\.\d+)?|[A-Za-z_][A-Za-z0-9_-]*)\s*\{',
            ).firstMatch(branches);
            if (branch == null) {
              throw const CatalogException(
                'Malformed ICU branch in translation.',
              );
            }
            final open = branch.end - 1;
            final end = _closingBrace(branches, open);
            scan(branches.substring(open + 1, end));
            branches = branches.substring(end + 1).trimLeft();
          }
        }
      }
      i = close;
    }
  }

  scan(message);
  return names;
}

int _closingBrace(String text, int open) {
  var depth = 0;
  for (var i = open; i < text.length; i++) {
    if (text[i] == '{') depth++;
    if (text[i] == '}' && --depth == 0) return i;
  }
  throw const CatalogException('Unmatched opening brace in translation.');
}

void _writeJson(File file, Object value) {
  file.writeAsStringSync(
    '${const JsonEncoder.withIndent('  ').convert(value)}\n',
  );
}
